"""Russian report from fixed replay outputs; no parameter decisions."""
from io_utils import read_csv

def build(out,summary,monthly,transitions,comparison,independent):
 def fmt(x):
  if isinstance(x,float):return f'{x:.6f}'
  if isinstance(x,str):
   try:return f'{float(x):.6f}' if '.' in x and 'T' not in x else x
   except ValueError:pass
  return str(x)
 def table(rows,columns):return '| '+' | '.join(k for k in columns)+' |\n| '+' | '.join('---' for _ in columns)+' |\n'+'\n'.join('| '+' | '.join(fmt(r.get(k,'')) for k in columns)+' |' for r in rows)+'\n'
 full=[r for r in summary if r['period']=='2023_2024'];c,a=full
 lines=['# T3/M15 — подтверждение растянутого пробоя одной свечой\n',
 '## Результат\n',
 f"Критерий не выполнен: отрицательных CLOSED и MTM месяцев стало {a['CLOSED_R_negative_months']} и {a['MTM_R_negative_months']} против {c['CLOSED_R_negative_months']} и {c['MTM_R_negative_months']} в CONTROL. Худший месяц и DD стали мельче, PF вырос, но число отрицательных месяцев не сократилось. Количество победителей >=2R: {c['winner_ge_2R_count']} → {a['winner_ge_2R_count']}; их суммарный вклад {c['winner_ge_2R_R']:.3f}R → {a['winner_ge_2R_R']:.3f}R.\n",
 'Единственная альтернатива сопоставлена с неизменным CONTROL. Критерий требует сокращения числа и глубины отрицательных месяцев и приемлемой сохранности сильных трендов. Порог неприемлемой потери трендов заранее не задан; ниже приведены абсолютные потери, без подбора такого порога.\n',
 table(full,['variant','CLOSED','OPEN_at_period_end','gross_PF','expectancy_R','gross_R','CLOSED_R_DD','MTM_R_DD']),
 table(full,['variant','CLOSED_R_negative_months','CLOSED_R_negative_sum','CLOSED_R_worst_month','CLOSED_R_worst_R','MTM_R_negative_months','MTM_R_negative_sum','MTM_R_worst_month','MTM_R_worst_R']),
 'Development — только 2023–2024 МСК. Обе системы идут непрерывно от исходного холодного старта, без перезапуска на границе года и без принудительного закрытия на конце. CLOSED-R DD — по frozen порядку exit Close/instrument/trade_id; MTM-R DD — по синхронизированной сетке наблюдённых Close с carry-forward последней отметки. Это суммы нормированных R, а не кривая денежного капитала.\n',
 '## Отдельно 2023 и 2024\n',table([r for r in summary if r['period']!='2023_2024'],['variant','period','CLOSED','OPEN_at_period_end','gross_PF','expectancy_R','gross_R','CLOSED_R_DD','MTM_R_DD','CLOSED_R_negative_months','MTM_R_negative_months','winner_ge_2R_count','winner_ge_2R_R']),
 'Год определяется frozen exit-bar Close. Годовые DD считаются внутри года относительно его начального уровня; позиции и их риски не сбрасываются. Поэтому CLOSED и MTM могут относить результат к разным месяцам и годам.\n',
 '## Конкретные изменения знака\n',table([r for r in transitions if r['sign_changed']],['month','basis','CONTROL_R','CONFIRM_R','transition']),
 table([dict(month=m,CONTROL_CLOSED_R=next(r['CLOSED_R'] for r in monthly if r['month']==m and r['variant']=='CONTROL'),CONFIRM_CLOSED_R=next(r['CLOSED_R'] for r in monthly if r['month']==m and r['variant']=='CONFIRM'),CONTROL_MTM_R=next(r['MTM_R'] for r in monthly if r['month']==m and r['variant']=='CONTROL'),CONFIRM_MTM_R=next(r['MTM_R'] for r in monthly if r['month']==m and r['variant']=='CONFIRM')) for m in sorted({r['month'] for r in monthly if r['CLOSED_R']<0 or r['MTM_R']<0})],['month','CONTROL_CLOSED_R','CONFIRM_CLOSED_R','CONTROL_MTM_R','CONFIRM_MTM_R']),
 'Все 48 пар месяц/база, включая месяцы без смены знака: MONTH_SIGN_TRANSITIONS.csv. Полный календарь и покрытие: MONTHLY.csv, COVERAGE.csv.\n',
 '## Сильные тренды и потери исходных победителей\n',table(full,['variant','winner_ge_2R_count','winner_ge_2R_R','gross_positive_R','gross_negative_R']),
 table([comparison],['original_ge2R_count','original_ge2R_R','original_ge2R_still_ge2R','original_ge2R_skipped','original_ge2R_to_nonpositive','original_ge2R_OPEN','original_ge2R_CONFIRMED_CLOSED_contribution_R']),
 table([comparison],['missed_profitable','missed_profitable_CONTROL_R','profitable_to_nonpositive','profitable_to_OPEN','profitable_reduced']),
 table(read_csv(out/'ORIGINAL_GE_2R_BY_YEAR.csv'),['signal_year','original_ge2R_count','CONTROL_R','retained_ge2R','skipped','to_nonpositive','OPEN','CONFIRM_CLOSED_contribution_R']),
 f"Общее количество >=2R уменьшилось на {100*(1-a['winner_ge_2R_count']/c['winner_ge_2R_count']):.1f}%, их вклад — на {100*(1-a['winner_ge_2R_R']/c['winner_ge_2R_R']):.1f}%. Вклад фиксированной исходной когорты уменьшился на {100*(1-comparison['original_ge2R_CONFIRMED_CLOSED_contribution_R']/comparison['original_ge2R_R']):.1f}%. Это раскрытая потеря трендов, а не автоматически приемлемый порог.\n",
 'Общий набор >=2R победителей альтернативы включает новые сделки. Отдельная исходная когорта удерживает те же instrument/signal Close/side: её вклад включает все CLOSED исходы, в том числе менее 2R и отрицательные; OPEN раскрыт отдельно и не заменён нулевой прибылью. ORIGINAL_GE_2R_WINNERS.csv содержит каждую исходную крупную сделку, LOST_AND_REDUCED_WINNERS.csv — все потерянные/уменьшенные исходные прибыли.\n',
 '## Входы, занятость и причинный порядок\n',table([comparison],['common_signals','missed_control_entries','new_confirm_entries','new_entries_R','missed_entries_CONTROL_R']),
 table(read_csv(out/'MECHANISM_SUMMARY.csv'),['signal_year','eligible_attempts','stretched_attempts','executed_confirmed','failed_price','outside_T1','missing_confirmation','missing_entry','unstretched_executed']),
 'Сделки сопоставлены по instrument/signal Close/side, а не по переиспользуемому frozen счётчику trade_id. TRADE_COMPARISON.csv показывает цену/время входа, исход и причину пропуска. Для общих CLOSED приведены entry penalty, exit delta и альтернативный PNL в CONTROL R0. Разность PNL = exit delta − entry penalty. Ни один готовый CSV сделок не служит входом симуляции.\n',
 table(read_csv(out/'SIGNAL_REASON_COUNTS.csv'),['variant','reason','count']),
 'CONTROL/CONFIRM_SIGNALS.csv.gz содержат все исходные сигналы, включая вне T1 и занятый инструмент, стадию ожидания, Close подтверждения и конечную причину. MARKS отражает фактическую позицию и отдельный резерв ожидания на каждой свече. STOPS содержит каждый stop test и обновление; TRADES/OPEN/SNAPSHOTS — конечные исходы и переносы.\n',
 'Растянутый исходный сигнал >=0.5 ATR ждёт ровно одну смежную M15. Close подтверждения строго дальше исходного Close и исходного Donchian, внутри T1 [10:00,18:00). Вход на следующем смежном Open. Провал, разрыв или выход из T1 завершает исходную попытку. Новый самостоятельный сигнал на Close отказа вправе начать собственную попытку; это не третья свеча старого сигнала. При успехе слот зарезервирован до execution Open. Не добавлены фильтры, повторное ожидание, подбор ATR/порогов или изменения R15.\n',
 'Initial Stop всегда 2 ATR исходной сигнальной свечи от фактической новой цены входа, trail 3.5 текущего ATR без изменений. High/Low подтверждающей свечи не используются для трейла будущей позиции. Stop-first; adverse Open fill, иначе касание старого stop. Новый trail действует только со следующей свечи. Execution bar уже проверяет Initial Stop.\n',
 '## CONTROL, независимость и воспроизводимость\n',
 'Изолированный полный CONTROL воспроизвёл PR518: 1114 CLOSED / 356 INITIAL_STOP, все журналы; дополнительно сверены поля M15 CONTROL PR560. Development CONTROL сверён со всеми исходными полями PR518 и entry/exit/risk полями PR562, включая OPEN на границе. CONTROL mismatch останавливает процесс до сравнения альтернативы.\n',
 f"Отдельный scalar verifier: {independent['rows']} строк / {independent['fields']} полей, максимальное абсолютное численное отличие {independent['max_abs_error']:.3g}; {independent['Decimal_calendar_and_aggregate_fields']} fresh CSV/Decimal проверок календаря/PF/R/expectancy. Дополнительный fresh CSV/Decimal verifier проверил {independent['independent_statistics']['fresh_CSV_Decimal_fields']} полей всех годовых/месячных метрик, DD и когортных сравнений. Features независимо пересчитаны streaming EWM PR518, исполнения — отдельным алгоритмом agenda. Предел независимости: тот же автор, внешняя человеческая или отдельная агентская экспертиза НЕ выполнена.\n",
 'Синтетические контракты проверяют обе реализации: порог включительно, LONG/SHORT, строгий Close, обе смежности, 18:00, исходный ATR, отсутствие до-входного trail, первый stop, резерв, новый сигнал после отказа, EOF и gap-fill. Prefix invariance и perturbation будущего OHLC подтверждают причинность признаков и ранее доступных событий. REPEATABILITY.json фиксирует первый и два свежих полных процесса после CODE_FREEZE, с direct bytes и SHA256 каждого generated artifact.\n',
 '## Ограничения данных и денежная исполнимость\n',
 '2023 — неполный N4: GLDRUBF начинается 11 июля, IMOEXF 14 ноября; в начале года торгуются только USD/CNY. Фактические gaps не заполняются. H1 — frozen ordinal blocks четырёх M15 по local Close-date, только полные смежные блоки; исторические rolling/EWM явно CROSS_DAY/CROSS_YEAR, H1AvailableAt <= signal Close. Midnight МСК сохранён. Одинаковые исходные данные и прогрев обеих систем не устраняют ограничение короткой истории.\n',
 '2025–2026 прочитаны только отдельным обязательным CONTROL reconciliation и маркированы RETROSPECTIVE_CONTROL_ONLY; альтернативы на них нет. Это не новый независимый OOS. Сигнальные цены после development endpoint не преобразуются development-парсером в числа. OPEN остаются цензурированными.\n',
 'Результаты GROSS_ONLY. R15=1.5% и nominal risk cap=6% не менялись. R replay не моделирует фактический капитал, integer qty, исторические ГО, tick-value и расходы. Frozen stops сохраняют исследовательские off-grid значения. Денежный Net, доходность и рублёвая DD — NOT_VALIDATED. CAPITAL_FEASIBILITY.json фиксирует отсутствующие входные данные и формулу qty, без чтения production registry.\n',
 'Параметры --round-trip-cost-R и --round-trip-slippage-R дают отдельную нормированную чувствительность на CLOSED сделки; по умолчанию 0 для точного Gross CONTROL. Она не заменяет реальные комиссии/проскальзывание FINAM и не доказывает исполнимый Net. Не использована для настройки правила.\n',
 '## Решение\n']
 improved=c['CLOSED_R_negative_months']>a['CLOSED_R_negative_months'] and c['MTM_R_negative_months']>a['MTM_R_negative_months'] and a['CLOSED_R_negative_sum']>c['CLOSED_R_negative_sum'] and a['MTM_R_negative_sum']>c['MTM_R_negative_sum']
 lines.append(('Число и суммарная глубина отрицательных CLOSED/MTM месяцев уменьшились. Сохранность сильных трендов требует отдельной оценки владельца по раскрытым потерям исходной когорты; автоматическое принятие не обосновано.' if improved else 'Правило не выполнило совместный критерий сокращения числа и глубины отрицательных CLOSED/MTM месяцев. Улучшение PF и expectancy не меняет этот вывод; оснований переносить правило в production по этому replay нет.')+'\n')
 lines.append('Только audit-каталог, один Draft PR. Без merge/auto-merge. LIVE H1, M15 robot, FINAM, Tasks, SQLite, Control Center и производственные параметры не читались, не запускались и не менялись.\n')
 (out/'REPORT_RU.md').write_text('\n'.join(lines))
